ALTER TABLE [dbo].[Yachts] ADD [SortOrder] [int] NOT NULL DEFAULT 0
GO

;WITH OrderedYachts AS
        (
            SELECT
                Id,
                ROW_NUMBER() OVER (ORDER BY Id) AS RowNumber
            FROM dbo.Yachts
        )
        UPDATE y
        SET SortOrder = oy.RowNumber * 10
        FROM dbo.Yachts y
        INNER JOIN OrderedYachts oy ON y.Id = oy.Id;
GO

